<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_module('budget');$pageTitle='Budget Reports';$activeMenu='budget-reports';
$year=(int)($_GET['year']??date('Y'));$rows=db()->prepare("SELECT d.name department,c.name category,SUM(b.allocated_amount) budget,COALESCE((SELECT SUM(e.amount) FROM expenses e WHERE e.department_id=d.id AND e.category_id=c.id AND e.status='Approved' AND YEAR(e.expense_date)=?),0) expenses FROM budgets b JOIN departments d ON d.id=b.department_id JOIN budget_categories c ON c.id=b.category_id WHERE b.approval_status='Approved' AND b.budget_year=? GROUP BY d.id,d.name,c.id,c.name ORDER BY d.name,c.name");$rows->execute([$year,$year]);$rows=$rows->fetchAll();require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><h1>Budget Reports</h1><p>Approved allocation versus actual expense consumption by department and category.</p></div><button onclick="window.print()" class="btn btn-light border no-print"><i class="fa-solid fa-print me-2"></i>Print / PDF</button></div><div class="card-panel"><div class="card-body"><form class="row g-2 mb-4 no-print"><div class="col-auto"><input type="number" class="form-control" name="year" value="<?=$year?>"></div><div class="col-auto"><button class="btn btn-primary">Apply Year</button></div></form><div class="table-responsive"><table class="table data-table"><thead><tr><th>Department</th><th>Category</th><th class="text-end">Budget</th><th class="text-end">Expenses</th><th class="text-end">Balance</th><th>Utilization</th></tr></thead><tbody><?php foreach($rows as $r):$bal=$r['budget']-$r['expenses'];$u=$r['budget']>0?$r['expenses']/$r['budget']*100:0;?><tr><td><?=e($r['department'])?></td><td><?=e($r['category'])?></td><td class="text-end"><?=money($r['budget'])?></td><td class="text-end"><?=money($r['expenses'])?></td><td class="text-end"><?=money($bal)?></td><td><?=number_format($u,1)?>%</td></tr><?php endforeach;?></tbody></table></div></div></div><?php require ROOT_PATH.'/includes/footer.php';?>
